<script setup lang="ts">import{onMounted,ref}from'vue';import{request}from'../api/client';interface Service{id:number;code:string;name:string;description:string;input_enabled:boolean;menu:unknown}const items=ref<Service[]>([]),selected=ref<Service|null>(null),reason=ref('');async function load(){items.value=await request<Service[]>('/v1/ops/service-accounts')}async function save(){if(!selected.value)return;await request('/v1/ops/service-accounts',{method:'POST',body:JSON.stringify({...selected.value,reason:reason.value,avatar_asset_id:0})});selected.value=null;await load()}onMounted(load)</script><template><div class="page"><div class="heading"><div><h1>服务号</h1><p>系统通知、支付通知、输入区和菜单配置</p></div><button @click="load">刷新</button></div><div class="table"><table><thead><tr><th>服务号</th><th>说明</th><th>输入</th><th></th></tr></thead><tbody><tr v-for="s in items" :key="s.id"><td><strong>{{s.name}}</strong><small>{{s.code}}</small></td><td>{{s.description}}</td><td>{{s.input_enabled?'开启':'关闭'}}</td><td><button class="link" @click="selected={...s};reason=''">编辑</button></td></tr></tbody></table></div><div v-if="selected" class="backdrop" @click.self="selected=null"><form class="dialog" @submit.prevent="save"><h2>编辑服务号</h2><label>名称<input v-model.trim="selected.name" required></label><label>说明<textarea v-model.trim="selected.description"></textarea></label><label class="check"><input v-model="selected.input_enabled" type="checkbox">允许用户输入</label><label>修改原因<textarea v-model.trim="reason" required minlength="2"></textarea></label><div class="actions"><button type="button" @click="selected=null">取消</button><button class="primary">保存</button></div></form></div></div></template><style scoped>@import '../design/admin-page.css';</style>
